package com.leetcode.backend.dto; import com.leetcode.backend.model.*; import java.time.*;
public record ContestResponse(Long id,String title,String slug,String description,String rulesText,String accent,LocalDateTime startAt,LocalDateTime endAt,ContestStatus status,ContestVisibility visibility,boolean registered,long registrationCount){public static ContestResponse from(Contest c,boolean registered,long count){return new ContestResponse(c.getId(),c.getTitle(),c.getSlug(),c.getDescription(),c.getRulesText(),c.getAccent(),c.getStartAt(),c.getEndAt(),c.derivedStatus(),c.getVisibility(),registered,count);}}
